// Import the Verus prelude so we can use Vec, requires, ensures, etc.
use vstd::prelude::*;

verus! {
    /// solve maps an integer `x` in [1,3000] to one of two 4-character sequences:
    ///   if x < 1200, returns ['A','B','C','\n']
    ///   otherwise,   returns ['A','R','C','\n']
    pub fn solve(x: i32) -> Vec<char> {
        // -------------------------------------------------------------------
        // Specification
        // -------------------------------------------------------------------
        // Precondition: x is in [1,3000]
        requires(x >= 1 && x <= 3000);
        // Postcondition: result has length exactly 4
        ensures(|res: &Vec<char>| res.len() == 4);
        // Postcondition: exactly one of the two allowed sequences
        ensures(|res: &Vec<char>|
            if x < 1200 {
                *res == vec!['A','B','C','\n']
            } else {
                *res == vec!['A','R','C','\n']
            }
        );

        // -------------------------------------------------------------------
        // Implementation
        // -------------------------------------------------------------------
        let mut result: Vec<char> = Vec::new();
        // first character is always 'A'
        result.push('A');
        // second character depends on x
        if x < 1200 {
            result.push('B');
        } else {
            result.push('R');
        }
        // third character is always 'C'
        result.push('C');
        // fourth character is always newline
        result.push('\n');

        result
    }
}